{
  "name": "MC1电机控制器",
  "name_en": "MC1 Motor Controller",
  "manufacturer": "Qubitekk",
  "description": "MC1是一种用于驱动和定位线性执行器的电机控制器，可设置步进增量、行程上下限，并执行居中、复位和定点移动等操作。在实验室中，它可用于对位置进行重复扫描与调整，常见于配合线性执行器进行Hong–Ou–Mandel（HOM）干涉谷测量等实验。",
  "description_en": "The MC1 is a motor controller used to drive and position a linear actuator. It supports step increment control, travel limits, centering, reset, and point-to-point motion. In the lab, it is used for repeatable position scanning and adjustment, such as operating a linear actuator for Hong–Ou–Mandel (HOM) dip measurements.",
  "tag_hints": [
    "motor control",
    "linear actuator positioning",
    "travel limit control",
    "step positioning",
    "HOM dip measurement",
    "optical delay scanning"
  ],
  "actions": [
    {
      "action_name": "auto-center",
      "description": "使执行器自动移动到行程中心位置。",
      "description_en": "Move the actuator automatically to the center of its travel range."
    },
    {
      "action_name": "auto-increment",
      "description": "获取/设置步进增量。",
      "description_en": "Get/set the stepping increment."
    },
    {
      "action_name": "auto-inertia",
      "description": "获取/设置惯性参数。",
      "description_en": "Get/set the inertia parameter."
    },
    {
      "action_name": "auto-is_centering",
      "description": "查询设备当前是否处于居中过程。",
      "description_en": "Query whether the device is currently in its centering phase."
    },
    {
      "action_name": "auto-lower_limit",
      "description": "获取/设置行程下限。",
      "description_en": "Get/set the lower travel limit."
    },
    {
      "action_name": "auto-move",
      "description": "将执行器移动到指定步数位置。",
      "description_en": "Move the actuator to a specified step position."
    },
    {
      "action_name": "auto-reset",
      "description": "将执行器送到某一侧行程限位位置以复位。",
      "description_en": "Send the actuator to one end of its travel range to reset it."
    },
    {
      "action_name": "auto-setting",
      "description": "获取/设置控制器设置参数。",
      "description_en": "Get/set a controller setting parameter."
    },
    {
      "action_name": "auto-step_size",
      "description": "获取/设置步长。",
      "description_en": "Get/set the step size."
    },
    {
      "action_name": "auto-upper_limit",
      "description": "获取/设置行程上限。",
      "description_en": "Get/set the upper travel limit."
    },
    {
      "action_name": "auto-internal_position",
      "description": "获取内部位置计数。",
      "description_en": "Get the internal position counter."
    },
    {
      "action_name": "auto-firmware",
      "description": "获取固件版本。",
      "description_en": "Get the firmware version."
    },
    {
      "action_name": "auto-move_timeout",
      "description": "获取移动超时时间。",
      "description_en": "Get the move timeout."
    }
  ]
}

